import {downloadLocal} from './browser-documents.mjs?v=117';
export const LOCAL_STAGES=['Applied','Referred','Recruiter reached out','Assessment / next step','Interview','Offer','Rejected','Withdrawn'];
const KEY='nextrole-local-applications-v1',make=(tag,text)=>{const e=document.createElement(tag);if(text)e.textContent=text;return e;};
export function cleanApplication(row){if(!row||typeof row!=='object'||!LOCAL_STAGES.includes(row.status))throw Error('Invalid application status.');const out={};for(const key of ['id','company','role','reference','url','referrer','notes','date']){if(row[key]!==undefined&&typeof row[key]!=='string')throw Error('Invalid application field.');out[key]=String(row[key]||'').trim();if(out[key].length>(key==='notes'?2000:500))throw Error('Application details are too long.');}if(!out.company||!out.role)throw Error('Add a company and job title.');if(out.url){const url=new URL(out.url);if(url.protocol!=='https:'||url.username||url.password)throw Error('Use a complete https job link.');}if(out.date&&!/^\d{4}-\d{2}-\d{2}$/.test(out.date))throw Error('Check the application date.');out.status=row.status;out.events=(Array.isArray(row.events)?row.events:[]).slice(-100).map(e=>{if(!LOCAL_STAGES.includes(e.status)||!Number.isFinite(e.at))throw Error('Invalid status history.');return {status:e.status,at:e.at};});return out;}
export function readApplicationBackup(text){const data=JSON.parse(text);if(data.format!=='nextrole-applications'||data.version!==1||!Array.isArray(data.applications)||data.applications.length>500)throw Error('Choose a NextRole applications backup (maximum 500 entries).');const rows=data.applications.map(cleanApplication);if(rows.some(r=>!r.id)||new Set(rows.map(r=>r.id)).size!==rows.length)throw Error('Backup has missing or duplicate application IDs.');return rows;}
export function setupLocalApplications({storage=localStorage}){
 const root=make('section');root.id='applications-view';root.className='content application-tracker';root.hidden=true;document.querySelector('main').append(root);
 root.innerHTML='<div class="eyebrow">YOUR APPLICATIONS</div><h1>Applications</h1><p>Track applications and referrals on this device. Download a backup before changing browsers or clearing browser data.</p><div class="application-toolbar"><label>Status<select data-filter aria-label="Filter applications by status"><option>All statuses</option></select></label><label>Search<input data-search type="search" aria-label="Search applications by company, role or job ID" placeholder="Company, role or job ID"></label><button type="button" data-add>Add application</button><button type="button" class="secondary" data-export>Download backup</button><label class="secondary">Restore backup<input data-import type="file" accept=".json,application/json"></label></div><p role="status" data-message></p><button type="button" class="secondary" data-undo hidden>Undo removal</button><div data-list></div>';
 const q=s=>root.querySelector(s),message=q('[data-message]');let removed=null;let rows=[];try{const saved=JSON.parse(storage.getItem(KEY)||'[]');if(!Array.isArray(saved)||saved.length>500)throw Error('Invalid stored applications');rows=saved.map(cleanApplication);}catch{message.textContent='Saved applications could not be read. Restore a backup if you have one.';}
 for(const stage of LOCAL_STAGES){const o=make('option',stage);q('[data-filter]').append(o);}
 const editor=make('dialog');editor.className='public-guide';document.body.append(editor);
 function persist(next){if(next.length>500)throw Error('This browser can hold up to 500 application records.');storage.setItem(KEY,JSON.stringify(next));rows=next;render();}
 function render(){const host=q('[data-list]');host.replaceChildren();const query=q('[data-search]').value.trim().toLowerCase(),stage=q('[data-filter]').value;for(const row of rows.filter(r=>(stage==='All statuses'||r.status===stage)&&[r.company,r.role,r.reference,r.referrer].join(' ').toLowerCase().includes(query))){const card=make('article');card.className='application-record';card.append(make('span',row.status),make('h2',row.role),make('p',row.company+(row.reference?' · Job ID: '+row.reference:'')));if(row.referrer)card.append(make('p','Referred by: '+row.referrer));if(row.notes)card.append(make('p',row.notes));const status=make('select');status.setAttribute('aria-label','Status for '+row.role+' at '+row.company);for(const value of LOCAL_STAGES){const o=make('option',value);o.value=value;o.selected=value===row.status;status.append(o);}status.onchange=()=>{try{persist(rows.map(r=>r.id===row.id?{...r,status:status.value,events:[...r.events,{status:status.value,at:Date.now()}]}:r));message.textContent='Status saved on this device.';}catch{status.value=row.status;message.textContent='Browser storage is full or unavailable. Your previous status was kept.';}};const edit=make('button','Edit details');edit.type='button';edit.className='secondary';edit.onclick=()=>openEditor(row);const remove=make('button','Remove');remove.type='button';remove.className='secondary';remove.onclick=()=>{try{persist(rows.filter(r=>r.id!==row.id));removed=row;q('[data-undo]').hidden=false;message.textContent='Application removed. You can undo this until this page is closed.';}catch{message.textContent='Could not update browser storage. The application was kept.';}};card.append(status,edit,remove);if(row.url){const a=make('a','Open job ↗');a.href=row.url;a.target='_blank';a.rel='noopener noreferrer';card.append(a);}if(['Interview','Assessment / next step'].includes(row.status)){const a=make('a','Find company interview experiences ↗');const u=new URL('https://www.google.com/search');u.searchParams.set('q',row.company+' '+row.role+' interview experience questions');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';card.append(make('p','Prepare using public interview reports; these are not guaranteed questions.'),a);}const timeline=make('ol');timeline.className='application-timeline';for(const event of row.events)timeline.append(make('li',event.status+' · '+new Date(event.at).toLocaleDateString()));card.append(timeline);host.append(card);}if(!host.children.length)host.append(make('p',rows.length?'No applications match these filters.':'No applications yet. Add one after applying or receiving a referral.'));}
 function openEditor(row=null){editor.innerHTML='<button type="button" class="inbox-close" aria-label="Close application editor">×</button><form><h2>'+(row?'Edit application':'Add application')+'</h2><label>Company<input name="company" required maxlength="500"></label><label>Job title<input name="role" required maxlength="500"></label><label>Job ID (optional)<input name="reference" maxlength="500"></label><label>Job link (optional)<input name="url" type="url" maxlength="500"></label><label>Date applied<input name="date" type="date"></label><label>Status<select name="status"></select></label><label>Referred by (optional)<input name="referrer" maxlength="500"></label><label>Notes<textarea name="notes" maxlength="2000"></textarea></label><p role="alert"></p><button type="submit">Save application</button></form>';
 const form=editor.querySelector('form');for(const stage of LOCAL_STAGES)form.elements.status.append(make('option',stage));if(row)for(const key of ['company','role','reference','url','date','status','referrer','notes'])form.elements[key].value=row[key];editor.querySelector('.inbox-close').onclick=()=>editor.close();form.onsubmit=e=>{e.preventDefault();try{const value=cleanApplication({...Object.fromEntries(new FormData(form)),id:row?.id||crypto.randomUUID(),events:row?.events||[]});if(!row||value.status!==row.status)value.events.push({status:value.status,at:Date.now()});persist(row?rows.map(r=>r.id===row.id?value:r):[value,...rows]);editor.close();message.textContent='Application saved on this device.';}catch(error){editor.querySelector('[role=alert]').textContent=error.name==='QuotaExceededError'?'Browser storage is full. Download your backup before making more changes.':error.message;}};editor.showModal();}
 q('[data-undo]').onclick=()=>{if(!removed)return;try{persist(rows.some(r=>r.id===removed.id)?rows:[removed,...rows]);removed=null;q('[data-undo]').hidden=true;message.textContent='Application restored.';}catch{message.textContent='Could not restore the application. Try again.';}};q('[data-add]').onclick=()=>openEditor();q('[data-filter]').onchange=render;q('[data-search]').oninput=render;
 q('[data-export]').onclick=()=>downloadLocal(JSON.stringify({format:'nextrole-applications',version:1,applications:rows},null,2),'nextrole-applications-backup.json','application/json');
 q('[data-import]').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error('Choose a backup smaller than 2 MB.');const imported=readApplicationBackup(await file.text()),byId=new Map(rows.map(r=>[r.id,r]));let added=0;for(const row of imported)if(!byId.has(row.id)){byId.set(row.id,row);added++;}persist([...byId.values()]);message.textContent=added+' applications restored. Existing records were kept.';}catch(error){message.textContent=error.message;}e.target.value='';};render();
 return {root,refresh:render,render,hidePreparation(){},trackJob(){return true;}};
}
